import json
import os
import sys
import time
import urllib.error
import urllib.request
from collections import Counter
from datetime import datetime, timezone

BASE = "http://localhost:8080"
RAW = "/tmp/recon/raw"
MAX_ATTEMPTS = 60

token = None
events = Counter()


def note(msg):
    print(msg, file=sys.stderr, flush=True)


def raw_request(method, path, auth=False):
    headers = {}
    if auth:
        headers["Authorization"] = f"Bearer {token}"
    data = b"" if method == "POST" else None
    req = urllib.request.Request(BASE + path, method=method, headers=headers, data=data)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()


def retry_after_seconds(headers, body):
    val = headers.get("Retry-After")
    if val is None:
        try:
            val = json.loads(body).get("retry_after")
        except Exception:
            val = None
    try:
        return float(val)
    except (TypeError, ValueError):
        return None


def get_token():
    global token
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            st, h, b = raw_request("POST", "/token")
        except OSError as e:
            events["token_conn_error"] += 1
            note(f"token connection error ({e}); retry {attempt}")
            time.sleep(min(2 ** attempt, 30))
            continue
        if st == 200:
            token = json.loads(b)["token"]
            events["token_fetched"] += 1
            return
        events[f"token_status_{st}"] += 1
        note(f"token status {st}: {b[:200]!r}; retry {attempt}")
        time.sleep(min(2 ** attempt, 30))
    raise RuntimeError("could not obtain token")


def api_get(path):
    """Return (status, parsed_json). Retries until it gets 200 or 404."""
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            st, h, b = raw_request("GET", path, auth=True)
        except OSError as e:
            events["conn_error"] += 1
            note(f"{path}: connection error ({e}); retry {attempt}")
            time.sleep(min(2 ** attempt, 30))
            continue
        if st == 200:
            return st, json.loads(b)
        if st == 404:
            events["not_found"] += 1
            return st, None
        if st in (401, 403):
            events[f"auth_{st}"] += 1
            note(f"{path}: {st} {b[:200]!r}; refreshing token (attempt {attempt})")
            get_token()
            continue
        if st == 429:
            events["rate_limited"] += 1
            wait = retry_after_seconds(h, b)
            note(f"{path}: 429 headers={{Retry-After: {h.get('Retry-After')}}} body={b[:200]!r}")
            time.sleep((wait if wait is not None else 2) + 0.5)
            continue
        events[f"status_{st}"] += 1
        note(f"{path}: status {st} body={b[:200]!r}; retry {attempt}")
        time.sleep(min(2 ** attempt, 30))
    raise RuntimeError(f"gave up on {path} after {MAX_ATTEMPTS} attempts")


def fetch_all_pages():
    pages = []
    page = 1
    while True:
        st, body = api_get(f"/orders?page={page}")
        assert st == 200
        with open(os.path.join(RAW, f"orders-page-{page:03d}.json"), "w") as f:
            json.dump(body, f)
        pages.append(body)
        note(f"page {page}/{body['total_pages']}: {len(body['items'])} items, next={body['next']!r}")
        if body["next"] is None:
            break
        expected_next = f"/orders?page={page + 1}"
        if body["next"] != expected_next:
            note(f"  unexpected next value {body['next']!r}, expected {expected_next!r}")
        page += 1
        if page > body["total_pages"] + 5:
            raise RuntimeError("runaway pagination")
    return pages


def main():
    get_token()
    pages = fetch_all_pages()

    listing_rows = 0
    total_pages = pages[0]["total_pages"]
    fetched_pages = [p["page"] for p in pages]
    if fetched_pages != list(range(1, len(pages) + 1)):
        raise RuntimeError(f"unexpected page sequence {fetched_pages}")
    if len(pages) != total_pages:
        raise RuntimeError(f"fetched {len(pages)} pages but total_pages={total_pages}")

    by_id = {}
    duplicates = 0
    conflicts = []
    for p in pages:
        for item in p["items"]:
            listing_rows += 1
            oid = item["id"]
            if oid in by_id:
                duplicates += 1
                if by_id[oid] != item:
                    conflicts.append(oid)
            else:
                by_id[oid] = item

    note(f"listing rows={listing_rows} distinct={len(by_id)} duplicates={duplicates} conflicting_dupes={len(conflicts)}")
    status_counts = Counter(o["status"] for o in by_id.values())
    note(f"status counts (raw, all): {dict(status_counts)}")

    start = datetime(2025, 3, 1, tzinfo=timezone.utc)
    end = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive; covers 31 May inclusive

    qualifying = []
    odd = []
    for o in by_id.values():
        if o["status"] != "shipped":
            continue
        ts = o["placed_at"]
        try:
            dt = datetime.fromisoformat(ts)
        except ValueError:
            odd.append(("bad_timestamp", o))
            continue
        if dt.tzinfo is None:
            odd.append(("naive_timestamp", o))
            continue
        dt_utc = dt.astimezone(timezone.utc)
        if start <= dt_utc < end:
            qualifying.append((o, dt_utc))

    note(f"qualifying orders: {len(qualifying)}; anomalies: {len(odd)}")
    for kind, o in odd:
        note(f"  {kind}: {o}")

    amount_types = Counter(type(o["amount_cents"]).__name__ for o, _ in qualifying)
    note(f"amount_cents types among qualifying: {dict(amount_types)}")

    customers = {}
    needed = sorted({o["customer_id"] for o, _ in qualifying})
    note(f"distinct customers to look up: {len(needed)}")
    for cid in needed:
        st, body = api_get(f"/customers/{cid}")
        if st == 200:
            customers[cid] = body
            with open(os.path.join(RAW, f"customer-{cid}.json"), "w") as f:
                json.dump(body, f)
        else:
            customers[cid] = None
            note(f"customer {cid} not found")

    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    per_order = []
    missing = []
    for o, dt_utc in qualifying:
        c = customers.get(o["customer_id"])
        if c is None:
            missing.append(o["id"])
            continue
        pct = c["discount_pct"]
        if not isinstance(pct, int) or not 0 <= pct <= 100:
            note(f"odd discount_pct {pct!r} for {o['customer_id']}")
        amt = o["amount_cents"]
        # round half up to whole cent: amt * (100 - pct) / 100, all integer arithmetic
        num = amt * (100 - pct)
        discounted = (num + 50) // 100
        per_order.append((o["id"], amt, pct, discounted, c["region"]))
        total += discounted
        region = c["region"]
        if region not in by_region:
            note(f"unexpected region {region!r} for {o['customer_id']}")
            by_region.setdefault(region, 0)
        by_region[region] += discounted

    if missing:
        raise RuntimeError(f"orders with unknown customers: {missing}")

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    assert sum(by_region.values()) == total
    with open("/tmp/recon/result_candidate.json", "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    with open("/tmp/recon/per_order.json", "w") as f:
        json.dump(per_order, f)

    note(f"events: {dict(events)}")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

